import{_ as p,F as d,W as o,X as s,Y as r,Z as n,$ as a,a1 as i}from"./framework-af1ddc77.js";const l={},h={href:"https://info.tsinghua.edu.cn/f/info/xxfb_fg/xnzx/template/detail?xxid=3428ae959bf3420e8b2d12ca428d5c75",target:"_blank",rel:"noopener noreferrer"},f={href:"https://thubook.help/thucourse/",target:"_blank",rel:"noopener noreferrer"},u={href:"https://mp.weixin.qq.com/s/D2X-yNmI_WqfWUamt43R4w",target:"_blank",rel:"noopener noreferrer"},g={href:"https://info.tsinghua.edu.cn/f/info/route?id=route691a499e1d184425a732126f968ce561",target:"_blank",rel:"noopener noreferrer"},x={href:"https://info.tsinghua.edu.cn/f/info/route?id=route691a499e1d184425a732126f968ce561",target:"_blank",rel:"noopener noreferrer"};function b(m,e){const t=d("ExternalLinkIcon");return o(),s("div",null,[e[10]||(e[10]=r("h1",{id:"选课",tabindex:"-1"},[r("a",{class:"header-anchor",href:"#选课","aria-hidden":"true"},"#"),n(" 选课")],-1)),e[11]||(e[11]=r("p",null,"选课是根据“培养方案”，在“选课系统”上选择某一老师的某节课，然后在下学期根据自己所选课的不同，去自己去各个教室找老师上课。",-1)),e[12]||(e[12]=r("h2",{id:"培养方案和教学计划",tabindex:"-1"},[r("a",{class:"header-anchor",href:"#培养方案和教学计划","aria-hidden":"true"},"#"),n(" 培养方案和教学计划")],-1)),e[13]||(e[13]=r("p",null,"培养方案和教学计划由教务负责的老师根据每个专业及院系的不同制定，分别主要规定了每个专业毕业的课程修读要求和每个学期建议修读的课程。例如某专业，大一上学期上《微积分A(1)》，大一下学期上《微积分A(2)》，均为必修，等等。",-1)),e[14]||(e[14]=r("p",null,"培养方案中的课程属性包括必修、限选和任选。必修，系指毕业时必须修读该课程并取得合格成绩；限选，多数时候系指毕业时需在包含该课程的该课组中修满一定的学分；任选，系指培养方案外自行修读的课程，部分专业亦有极少量学分要求的专业任选课。",-1)),e[15]||(e[15]=r("p",null,"课程属性为任选的课可以自己计P/F，不计入GPA（见下）。",-1)),r("p",null,[e[1]||(e[1]=n("2020-2025级所有院系的培养方案与教学计划：",-1)),r("a",h,[e[0]||(e[0]=n("培养方案与指导性教学计划",-1)),a(t)])]),e[16]||(e[16]=r("p",null,"2026级的汇总版本尚未更新，同学们可去各院系官网自行查阅。",-1)),e[17]||(e[17]=r("h2",{id:"选课系统",tabindex:"-1"},[r("a",{class:"header-anchor",href:"#选课系统","aria-hidden":"true"},"#"),n(" 选课系统")],-1)),e[18]||(e[18]=r("p",null,"培养方案只是规定你需要上某门课，但是在清华每门课都有很多老师教授，培养方案并不规定你必须上某个老师的课。学校在选课期间会开放选课系统左侧边栏开课信息底下的“以往选课学生推荐度”和“学生评教优秀课堂”，大家会在上面选择自己感兴趣，看好的老师。比如《微积分A》 ，有甲老师在教，乙老师在教，大家可以根据自己的喜好和时间安排，来选择一个老师的课。",-1)),r("p",null,[e[3]||(e[3]=n("也可以参看",-1)),r("a",f,[e[2]||(e[2]=n("THU选课社区",-1)),a(t)]),e[4]||(e[4]=n("的选课评价并书写自己的选课评价！",-1))]),e[19]||(e[19]=i('<h2 id="选课流程" tabindex="-1"><a class="header-anchor" href="#选课流程" aria-hidden="true">#</a> 选课流程</h2><h3 id="预选-选课报名阶段" tabindex="-1"><a class="header-anchor" href="#预选-选课报名阶段" aria-hidden="true">#</a> 预选（选课报名阶段）</h3><p>一般某个学期的预选在上一个学期的第13-14周，新生第一次选课的预选在军训期间。</p><p><strong>除新生预选之外</strong>，需填报志愿选课。每个选课属性各最多有一门课是第一志愿，最多有两门课是第二志愿。体育课最多有一门课是第一志愿，最多有一门课是第二志愿。即总共最多四个第一志愿（必限任各一个，体育一个），七个第二志愿（必限任各两个，体育一个）。第三志愿数量无限。</p><p>新生第一次选课处于新手保护期，只有必修、限选和任选的第三志愿，这大大减少了选课的博弈成分，</p><p>预选阶段中，自早八点到晚八点每隔四个小时统计一次“志愿填报情况”，可在选课系统中查看。强烈建议根据之调整自己的选课及选课志愿，减少掉课概率。</p><p>报名结束后，系统进行抽签处理（五道口大赌场，见下）。本科生体育课的选课优先级是根据填报志愿等级确定的，高志愿课程一旦选中，则低志愿课程自动删除。</p><p>建议在预选时选重修课程。重修选课不需填报志愿，直接选中，不受课容量限制。（数学系、数学教学中心、外文系、语言中心课程、写作与沟通、北大、北外课程的重修选课受课容量限制，即这些课程如有重修选课，课余量会相应减少。）</p><h4 id="抽签" tabindex="-1"><a class="header-anchor" href="#抽签" aria-hidden="true">#</a> 抽签</h4><p>由于同一门课可能有超过课容量的同学选择，所以会先进行志愿抽签，志愿优先级：</p><p>必修一 &gt; 必修二 &gt; 必修三 &gt; 限选一 &gt; 限选二 &gt; 限选三 &gt; 任选优先 &gt; 任选一 &gt; 任选二 &gt; 任选三</p><p>只有高优先级的全部抽完，才会在下一优先级中抽取。未抽中的同学，会随机进入wl（waiting list）等待候补，如果已经选中的同学退课，则候补队列中的同学自动补上。注意，<strong>体育课不实行waiting list</strong>，未抽中的同学需要手动选择其他体育课。</p><p>上述必修、限选、任选，系指选课系统中的选课属性。 选课系统中的“课程属性”与“选课属性”是两个不同的概念：课程属性是以学生主修专业培养方案为依据；选课属性是以当学期主修专业教学计划为依据。未列入当学期教学计划的必修、限选课程，其选课属性为任选，但课程属性仍为必修或限选。</p><p>例如，某专业大一上学期教学计划中上必修课《微积分A(1)》，则该课程选课属性为必修，而该学期教学计划中没有《英语听说交流A》，则该课程选课属性为任选，尽管该课程的课程属性为必修。</p><p>外语课、通识选修课和《形势与政策》的选课属性在每一个学期都是任选，尽管他们的课程属性为必修或限选。</p>',15)),r("p",null,[r("a",u,[e[5]||(e[5]=n("选课系统操作指南",-1)),a(t)])]),r("p",null,[r("a",g,[e[6]||(e[6]=n("Waiting List方案",-1)),a(t)])]),e[20]||(e[20]=r("h3",{id:"正选和补退选-选课调整阶段",tabindex:"-1"},[r("a",{class:"header-anchor",href:"#正选和补退选-选课调整阶段","aria-hidden":"true"},"#"),n(" 正选和补退选（选课调整阶段）")],-1)),e[21]||(e[21]=r("p",null,"一般正选在预选的下一周，新生第一次选课没有正选。补退选第一阶段一般在该学期的第一周，补退选第二阶段一般在该学期的第二周。",-1)),r("p",null,[e[8]||(e[8]=n("正选和补退选第一阶段可以做的事情相同：全部课程可选可删，先选先得，选满后实行",-1)),r("a",x,[e[7]||(e[7]=n("Waiting List方案",-1)),a(t)]),e[9]||(e[9]=n("。即可以删掉课（不计W），也可以增加选课或进入某个课程的队列末尾。",-1))]),e[22]||(e[22]=i('<p>补退选第二阶段不可以增加选课，只能删课（不计W）。</p><h3 id="二级选课" tabindex="-1"><a class="header-anchor" href="#二级选课" aria-hidden="true">#</a> 二级选课</h3><p>一般在正选后几天。</p><p>实验课等课程必须在二级选课期间选择二级课，先选先得，选满为止。具体是在二级选课期间点二级选课界面，上面会显示所有需要二级选课的课程，课程名右侧有“二级选课”四个字，点它，即进入二级选课界面，选择合适的项目即可。</p><p>不要忘了二级选课，如果没有二级选课或选的项目不够可能需要联系授课老师。</p><p>微积分等数学课显示需要二级选课但实际上不需要进行二级选课。</p><h3 id="退课" tabindex="-1"><a class="header-anchor" href="#退课" aria-hidden="true">#</a> 退课</h3><p>退课阶段所退课程在成绩单上记录“W”（Withdrew），后八周开课的课程退课不记W。记W，对GPA没有任何影响，绝大多数人也不会过问。因此若学业压力过大或认为必要，建议适量退课。</p><p>退课（第一阶段）：一般在第6周，除本科生体育课、北外课程不可退课外，其他课程均可退课。</p><p>退课（第二阶段）：一般在第10周，只允许后八周开课的课程退课  、允许本科生“综合论文训练”退课  ，其他课程、北大、北外课程均不可退课。（注：后八周开课的课程是指从第9周及以后开始上课的课程）</p><h3 id="选择课程以p-f记载" tabindex="-1"><a class="header-anchor" href="#选择课程以p-f记载" aria-hidden="true">#</a> <strong>选择课程以P/F记载</strong></h3><p>在“课程属性”为“任选”的已选课程中选择<strong>一门</strong>，其成绩记为P（Passing）或 F（Failure），无绩点。选择课程以P/F记载，是在“课程属性”（培养方案中规定的）为“任选”的课程中进行选择。</p><h2 id="上课" tabindex="-1"><a class="header-anchor" href="#上课" aria-hidden="true">#</a> 上课</h2><p>大学上课和高中也不一样。同一门课，每个老师的上课时间和上课地点都不尽相同。比如微积分A，甲老师可能每周一早上8:00到9:35在X教学楼的S1教室上课，乙老师可能每周三9:50到12:15在Y教学楼的M3教室上课。所以大学上课需要自己在规定的时间进入指定的教室等老师来。众所周知，清华一是学校大，二是课间短。可能上一节课微积分在三教，下一节课制造工程体验就在李兆基，所以下课后需要飞奔去另一个教学楼赶去上课。</p><p>不能出勤一般需要请假，一般找助教或授课教师，有些时候病假需要提供校医院诊断。</p><p><s>（不过也可以统筹优化掉一些课程不去上课）</s></p><h2 id="防沉迷机制" tabindex="-1"><a class="header-anchor" href="#防沉迷机制" aria-hidden="true">#</a> 防沉迷机制</h2><p>为了防止大家沉迷学习，学校规定选课每学期除体育和重修外，绝大多数院系大一不超过26学分，部分院系大二大三不超过30学分。在选课的每一个过程中都有限制（若选某个课以后超出限制会显示选课失败）。如想解除限制，需申请特批学分，审批通过后才可选课，一般比较容易通过。</p><hr><p><em>上次修改时间：2026-9-1</em><em>贡献者：自76张广昱，未央56 W，为先55 phl</em></p>',20))])}const W=p(l,[["render",b],["__file","xuanke.html.vue"]]);export{W as default};
